export const SAMPLE_DER_CERT_HEX = ``;

export function samplesFor(toolId: string): ToolSample[] {
  switch (toolId) {
    case "x509":
      return [
        {
          id: "rsa-tls",
          label: "TLS Server Certificate",
          note: "RSA 2048-bit certificate with SANs and key usage",
          text: RSA_CERTIFICATE_PEM,
        },
        {
          id: "root-ca",
          label: "Root Certificate Authority",
          note: "Self-signed CA certificate with BasicConstraints CA:TRUE",
          text: CA_CERTIFICATE_PEM,
        },
      ];
    case "csr":
      return [
        {
          id: "ec-csr",
          label: "ECDSA P-256 CSR",
          note: "PKCS#10 Certificate Signing Request with requested SANs",
          text: ECDSA_CSR_PEM,
        },
      ];
    case "cert-converter":
      return [
        {
          id: "tls-cert",
          label: "TLS Certificate (PEM)",
          note: "Standard PEM certificate for PEM to DER, Certificate to PKCS#7, or Extract Public Key",
          text: RSA_CERTIFICATE_PEM,
        },
        {
          id: "rsa-private-key",
          label: "RSA Private Key (PEM)",
          note: "PKCS#8 private key for Private Key to PuTTY (.ppk v3) or PEM to DER conversion",
          text: RSA_PRIVATE_KEY_PEM,
        },
        {
          id: "putty-ppk",
          label: "PuTTY Private Key (.ppk)",
          note: "PuTTY v3 SSH/TLS private key for PuTTY (.ppk) to PEM Private Key conversion",
          text: SAMPLE_PPK_TEXT,
        },
        {
          id: "pkcs12-archive",
          label: "PKCS#12 Archive (.pfx / .p12 Base64)",
          note: "PKCS#12 keystore archive for PKCS#12 to PEM extraction or PKCS#12 Inspect (Password: password123)",
          text: SAMPLE_PKCS12_BASE64,
        },
        {
          id: "pkcs7-bundle",
          label: "PKCS#7 Certificate Bundle (.p7b PEM)",
          note: "PKCS#7 cryptographic message syntax bundle containing multiple certificates for PKCS#7 to PEM",
          text: SAMPLE_PKCS7_PEM,
        },
        {
          id: "cert-chain",
          label: "Certificate Chain Bundle (PEM)",
          note: "Multi-certificate PEM bundle for Split Chain / Bundle operation",
          text: CERTIFICATE_CHAIN_PEM,
        },
        {
          id: "csr-sample",
          label: "CSR (PKCS#10 PEM)",
          note: "PKCS#10 Certificate Signing Request to convert to DER or extract public key",
          text: ECDSA_CSR_PEM,
        },
        {
          id: "der-cert-hex",
          label: "DER Certificate (Hex)",
          note: "Raw binary DER encoded certificate in Hex format for DER to PEM conversion",
          text: SAMPLE_DER_CERT_HEX,
        },
      ];
    case "crl":
      return [
        {
          id: "crl-sample",
          label: "X.509 v2 CRL (Revocation List)",
          note: "RFC 5280 CRL containing revoked serial numbers and reason codes",
          text: SAMPLE_CRL_PEM,
        },
      ];
    case "cert-verifier":
      return [
        {
          id: "2tier-chain",
          label: "2-Tier Certificate Chain (Server + Root CA)",
          note: "Valid leaf server certificate cryptographically signed by issuing Root CA",
          text: SAMPLE_2TIER_CHAIN_PEM,
        },
        {
          id: "3tier-chain",
          label: "3-Tier Enterprise Chain (Server + Intermediate + Root CA)",
          note: "Enterprise PKI chain with subordinate issuing CA (ECDSA P-256)",
          text: SAMPLE_3TIER_CHAIN_PEM,
        },
        {
          id: "root-ca-anchor",
          label: "Root CA Trust Anchor",
          note: "Self-signed root certificate authority",
          text: SAMPLE_ROOT_CA_PEM,
        },
      ];
    case "cert-matcher":
      return [
        {
          id: "matched-keypair",
          label: "Matching RSA-2048 Certificate",
          note: "Certificate paired with the matching private key in the second input box",
          text: RSA_CERTIFICATE_PEM,
        },
      ];
    case "cert-diff":
      return [
        {
          id: "cert-comparison",
          label: "Original Certificate (Renewal Comparison)",
          note: "Primary certificate compared side-by-side against the second certificate input",
          text: SAMPLE_2TIER_SERVER_PEM,
        },
      ];
    case "csr-signer":
      return [
        {
          id: "ec-csr-signing",
          label: "ECDSA P-256 CSR to Sign",
          note: "PKCS#10 CSR with SANs ready to be signed into an active TLS certificate",
          text: ECDSA_CSR_PEM,
        },
      ];
    case "ocsp":
      return [
        {
          id: "ocsp-response-good",
          label: "RFC 6960 OCSP Response (Good)",
          note: "Base64-encoded OCSP revocation response verifying valid certificate status",
          text: SAMPLE_OCSP_RESPONSE_B64,
        },
      ];
    case "acme":
      return [
        {
          id: "acme-sample",
          label: "ACME Challenge Token",
          note: "RFC 8555 HTTP-01 and DNS-01 challenge calculation sample",
          text: "evaGxfADs6pSRb2LAv9IZf17Dt3juxGJ-PCt92wr-oA",
        },
      ];
    default:
      return [];
  }
}
